import type { AuditSection } from './audit-section-model';

export interface AssetInspection {
  /**
   * @displayName Asset Inspection ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Asset Inspection Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  assetInspectionName: string;
  /**
   * @displayName Asset Sequence
   * @validationRule Required for create/update operations
   */
  assetSequence: number;
  /**
   * @displayName Audit Section
   * @validationRule Required for create/update operations
   */
  auditSection: Pick<AuditSection, 'id' | 'auditSectionName'>;
  /**
   * @displayName Identifier
   * @validationRule Required for create/update operations
   */
  identifier: string;
  /**
   * @displayName Location Description
   */
  locationDescription?: string;
  /**
   * @displayName Serial Number
   */
  serialNumber?: string;
}

export const _AssetInspection = 'AssetInspection' as const;